import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.D8Tso2Ul.js";const h=JSON.parse('{"title":"Módulo: Encuestas","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/encuestas.md","filePath":"modulos/encuestas.md"}'),o={name:"modulos/encuestas.md"};function d(r,a,i,c,l,u){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="modulo-encuestas" tabindex="-1">Módulo: Encuestas <a class="header-anchor" href="#modulo-encuestas" aria-label="Permalink to &quot;Módulo: Encuestas&quot;">​</a></h1><p><strong>Ubicación:</strong> <code>Frontend/src/pages/Surveys.tsx</code> · <code>Backend/handlers/surveys/</code></p><p>Sistema de encuestas y evaluaciones para trabajadores. Permite levantar información de salud, clima de seguridad y evaluaciones de conocimiento, con lógica condicional.</p><h2 id="creacion-de-encuestas" tabindex="-1">Creación de encuestas <a class="header-anchor" href="#creacion-de-encuestas" aria-label="Permalink to &quot;Creación de encuestas&quot;">​</a></h2><p>Constructor de preguntas con distintos tipos:</p><table tabindex="0"><thead><tr><th>Tipo de pregunta</th><th>Uso</th></tr></thead><tbody><tr><td>Opción múltiple</td><td>Selección entre alternativas</td></tr><tr><td>Texto libre</td><td>Respuesta abierta</td></tr><tr><td>Escala numérica</td><td>Valoración (ej. 1 a 5)</td></tr><tr><td>Sí / No</td><td>Respuesta binaria</td></tr></tbody></table><p>Soporta <strong>lógica condicional (skip logic)</strong>: ciertas preguntas se muestran solo según respuestas anteriores.</p><h2 id="distribucion" tabindex="-1">Distribución <a class="header-anchor" href="#distribucion" aria-label="Permalink to &quot;Distribución&quot;">​</a></h2><ul><li>Asignación a trabajadores específicos.</li><li>Asignación por rol o área.</li><li>Programación de envío.</li></ul><p>Las asignaciones se registran con <code>personaId</code> (identidad unificada). Ver <a href="/manual/modulos/personas.html">Personas</a>.</p><h2 id="relacion-con-el-ds-44" tabindex="-1">Relación con el DS 44 <a class="header-anchor" href="#relacion-con-el-ds-44" aria-label="Permalink to &quot;Relación con el DS 44&quot;">​</a></h2><p>Las encuestas alimentan documentos como la <code>ENCUESTA_SALUD</code> (declaración de salud al ingreso), un insumo relevante para la evaluación de riesgos por cargo y la <a href="/manual/ds44/documentos-obligatorios.html">MIPPER</a>.</p><h2 id="estructura" tabindex="-1">Estructura <a class="header-anchor" href="#estructura" aria-label="Permalink to &quot;Estructura&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>surveyId      UUID</span></span>
<span class="line"><span>tenantId      FK</span></span>
<span class="line"><span>obraId        FK</span></span>
<span class="line"><span>preguntas     Lista de preguntas con tipo y lógica condicional</span></span>
<span class="line"><span>asignaciones  [{ personaId, estado }]</span></span>
<span class="line"><span>resultados    Respuestas agregadas</span></span></code></pre></div><h2 id="resultados" tabindex="-1">Resultados <a class="header-anchor" href="#resultados" aria-label="Permalink to &quot;Resultados&quot;">​</a></h2><p>Los resultados se agregan para análisis: distribución de respuestas, tasa de participación y resultados por área o cargo.</p><h2 id="endpoints-relacionados" tabindex="-1">Endpoints relacionados <a class="header-anchor" href="#endpoints-relacionados" aria-label="Permalink to &quot;Endpoints relacionados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Método</th><th>Ruta</th><th>Acción</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/surveys</code></td><td>Crear encuesta</td></tr><tr><td><code>GET</code></td><td><code>/surveys</code></td><td>Listar encuestas</td></tr><tr><td><code>GET</code></td><td><code>/surveys/{id}</code></td><td>Obtener encuesta</td></tr><tr><td><code>POST</code></td><td><code>/surveys/{id}/respond</code></td><td>Responder encuesta</td></tr><tr><td><code>GET</code></td><td><code>/surveys/{id}/results</code></td><td>Obtener resultados</td></tr></tbody></table>`,18)])])}const b=e(o,[["render",d]]);export{h as __pageData,b as default};
